import os
import boto3

def extract_tables(payload, config=None):
    config = config or {}
    client = boto3.client('textract', region_name=config.get('region', os.environ.get('AWS_DEFAULT_REGION', 'us-east-1')))
    response = client.analyze_document(Document={'Bytes': payload}, FeatureTypes=['TABLES'])
    blocks = response['Blocks']
    id_map = {b['Id']: b for b in blocks}
    tables = []
    for block in blocks:
        if block['BlockType'] == 'TABLE':
            rows = []
            for rel in block.get('Relationships', []):
                if rel['Type'] == 'CHILD':
                    for child_id in rel['Ids']:
                        child = id_map.get(child_id)
                        if child and child['BlockType'] == 'ROW':
                            cells = []
                            for cell_rel in child.get('Relationships', []):
                                if cell_rel['Type'] == 'CHILD':
                                    for cell_id in cell_rel['Ids']:
                                        cell = id_map.get(cell_id)
                                        if cell and cell['BlockType'] == 'CELL':
                                            cells.append({'text': cell.get('Text', ''), 'row_index': cell['RowIndex'], 'col_index': cell['ColumnIndex']})
                            rows.append(cells)
            tables.append(rows)
    result = tables
    return result
